semanticComparisonAndAuthorization.command:
node scripts/harness.mjs bounded -- node --input-type=module -e 'import assert from '\''node:assert/strict'\'';
import {readFileSync} from '\''node:fs'\'';
import {execFileSync} from '\''node:child_process'\'';
import {loadConfig} from '\''./scripts/lib/config.mjs'\'';
import {readAuthorityGrantRegistry} from '\''./scripts/lib/authority-grants.mjs'\'';
import {authorizeRegisteredEffects,authorizeRegisteredPublication} from '\''./scripts/lib/target-publish.mjs'\'';
const root=process.cwd();
const before=JSON.parse(execFileSync('\''git'\'',['\''show'\'','\''main:dotln.config.json'\''],{encoding:'\''utf8'\''}));
const after=JSON.parse(readFileSync('\''dotln.config.json'\''));
const expected=structuredClone(before);
const r=expected.repositories['\''dotln-angular'\''];
r.release={policy:'\''declared'\'',displayName:'\''DotLn Angular'\''};
r.baseDisposablePolicy='\''judge-only'\'';
r.authorityProfile.allowedEffects.push('\''release.close'\'');
r.authorityProfile.deniedEffects=r.authorityProfile.deniedEffects.filter(x=>x!=='\''release.close'\'');
expected.contributions={operatorAuthor:execFileSync('\''git'\'',['\''log'\'','\''--no-merges'\'','\''-1'\'','\''--format=%an <%ae>'\'','\''main'\''],{encoding:'\''utf8'\''}).trim()};
assert.deepEqual(after,expected);
for(const change of ['\''repositories.dotln-angular.release added'\'','\''repositories.dotln-angular.baseDisposablePolicy added'\'','\''contributions.operatorAuthor added'\'','\''repositories.dotln-angular.authorityProfile.allowedEffects appended release.close'\'','\''repositories.dotln-angular.authorityProfile.deniedEffects removed release.close'\''])console.log(change);
console.log('\''No other configuration key or value changed.'\'');
const oldGrants=JSON.parse(execFileSync('\''git'\'',['\''show'\'','\''main:packages/skeleton/loadouts/grants.json'\''],{encoding:'\''utf8'\''}));
const grants=JSON.parse(readFileSync('\''packages/skeleton/loadouts/grants.json'\''));
assert.equal(grants.length,1);
for(const key of ['\''grantId'\'','\''version'\'','\''grantedBy'\'','\''repo'\''])assert.deepEqual(grants[0][key],oldGrants[0][key]);
for(const key of ['\''effects'\'','\''operations'\''])assert.deepEqual(grants[0][key],[...oldGrants[0][key],'\''release.close'\'']);
assert.deepEqual(Object.keys(grants[0]),Object.keys(oldGrants[0]));
for(const hash of ['\''4f14c6c09512576abfd701335f4dd8a347694ff23785724422cb8d943b5d67aa'\'','\''01b3d03564fe733b600083183008b4fb46ee3350ae33469cd379121cc262a177'\''])assert.ok(grants[0].reason.includes(hash));
console.log('\''Grant delta: release.close appended to effects and operations; reason rewritten; all other fields unchanged.'\'');
const repository=loadConfig(root).repositories['\''dotln-angular'\''];
const registry=readAuthorityGrantRegistry(root);
authorizeRegisteredEffects(repository,registry,Date.now(),'\''WO-012'\'',['\''release.close'\'']);
authorizeRegisteredPublication(repository,registry,Date.now(),'\''WO-012'\'');
console.log('\''authorized: release.close and registered publication'\'');
const committedOnly=registry.filter(x=>x.grantedBy==='\''operator'\'');
authorizeRegisteredEffects(repository,committedOnly,Date.now(),'\''WO-012'\'',['\''repo.push'\'','\''pr.open'\'','\''pr.thread.resolve'\'','\''release.close'\'']);
console.log('\''authorized: all four effects through the committed operator grant'\'');'

